mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, sys, urllib.request, urllib.error
BASE = "http://localhost:8080"
tok = None
log = []
def get_token():
    global tok
    while True:
        try:
            r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST", data=b""))
            tok = json.load(r)["token"]; return
        except urllib.error.HTTPError as e:
            log.append(("token", e.code, dict(e.headers), e.read()[:200].decode()))
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(path):
    global tok
    for attempt in range(200):
        if tok is None: get_token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {tok}"})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            body = r.read()
            try:
                return 200, json.loads(body)
            except Exception:
                log.append((path, "badjson", body[:200].decode(errors="replace"))); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body = e.read()[:300].decode(errors="replace")
            log.append((path, e.code, {k: v for k, v in e.headers.items() if k.lower() in ("retry-after","www-authenticate")}, body))
            if e.code == 401: tok = None; continue
            if e.code == 404: return 404, body
            if e.code == 429:
                time.sleep(float(e.headers.get("Retry-After") or 1)); continue
            time.sleep(float(e.headers.get("Retry-After") or 0.5)); continue
        except Exception as e:
            log.append((path, "exc", repr(e))); time.sleep(0.5); continue
    raise RuntimeError("gave up on " + path)

pages = {}
path = "/orders?page=1"
seen_paths = set()
while path:
    code, d = get(path)
    assert code == 200, (path, d)
    pages[path] = d
    seen_paths.add(path)
    print(path, d.get("page"), d.get("total_pages"), len(d["items"]), d.get("next"), file=sys.stderr)
    path = d.get("next")
    if path in seen_paths: print("LOOP", path, file=sys.stderr); break
json.dump({"pages": pages, "log": log}, open("/tmp/recon/orders_raw.json", "w"))
print("log entries", len(log), file=sys.stderr)
EOF
python3 -I /tmp/recon/fetch.py

